from serving_runtime import RuntimeContext, MonitorContext, legacy_sample, basic_sample

TOOLS = [{'name': 'lookup', 'description': 'Look up a local project record', 'parameters': {'type': 'object', 'properties': {'record_id': {'type': 'string'}}, 'required': ['record_id']}}]
SYSTEM_PROMPT = 'Answer project questions using the supplied tools.'
CONTEXT = RuntimeContext(monitor_ctx=MonitorContext(project="eval-audit"), log_conversations=True, cancellation=True, replay=False)

def serve(request):
    return basic_sample(request, tools=TOOLS, context=CONTEXT, system_prompt=SYSTEM_PROMPT)
